import{_ as i,a as s,b as n,c as l,d,e as c,f as h,g,h as p,i as u,j as f,k as m,l as b,m as v,n as w,o as k,p as _,q as e,r as y,s as S,t as r,u as L,v as A,w as P,x,y as C,z as K,A as T,B as I,C as D,D as E,E as O}from"./chunks/cloudflare.KvEfh_SJ.js";import{_ as N}from"./chunks/pikube-technical-stacks.drawio.YJ_Qv9fO.js";import{_ as R,c as j,o as M,j as a,a0 as q,a as B,t as F}from"./chunks/framework.2ZoCBPOS.js";const Q=JSON.parse('{"title":"What is this project about?","description":"This project aims to establish a Kubernetes cluster, PiKube, at home, utilizing Raspberry Pis and Orange Pis. It focuses on automating deployment and configuration through IaC (Infrastructure as Code) and GitOps methodologies, employing tools such as Ansible and ArgoCD. Key features include automatic deployment of a K3s-based Kubernetes cluster, Longhorn for distributed block storage, Prometheus for monitoring, EFK+Loki for centralized log management, Velero and Restic for backup solutions, and Linkerd for service mesh architecture.","frontmatter":{"title":"What is this project about?","permalink":"/docs/1-project-architecture-purpose/1-project-purpose","description":"This project aims to establish a Kubernetes cluster, PiKube, at home, utilizing Raspberry Pis and Orange Pis. It focuses on automating deployment and configuration through IaC (Infrastructure as Code) and GitOps methodologies, employing tools such as Ansible and ArgoCD. Key features include automatic deployment of a K3s-based Kubernetes cluster, Longhorn for distributed block storage, Prometheus for monitoring, EFK+Loki for centralized log management, Velero and Restic for backup solutions, and Linkerd for service mesh architecture.","last_modified_at":"31-01-2024"},"headers":[],"relativePath":"1-project-architecture-purpose/todelete-1-project-purpose.md","filePath":"1-project-architecture-purpose/todelete-1-project-purpose.md"}'),V={name:"1-project-architecture-purpose/todelete-1-project-purpose.md"},G={id:"frontmatter-title",tabindex:"-1"};function H(o,t,z,U,$,W){return M(),j("div",null,[a("h1",G,[B(F(o.$frontmatter.title)+" ",1),t[0]||(t[0]=a("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":'Permalink to "{{ $frontmatter.title }}"'},"​",-1))]),t[1]||(t[1]=q('<p align="center"><img alt="pikube-logo" src="'+i+'" width="80%" height="%"></p><h2 id="project-scope-pikube-kubernetes-service" tabindex="-1">Project Scope: PiKube Kubernetes Service <a class="header-anchor" href="#project-scope-pikube-kubernetes-service" aria-label="Permalink to &quot;Project Scope: PiKube Kubernetes Service&quot;">​</a></h2><p>The primary goal of this project is the creation of a home-based Kubernetes cluster using ARM bare metal nodes, specifically Raspberry Pis and Orange Pis. Emphasis is placed on automation of deployment and configuration, leveraging Infrastructure as Code (IaC) and GitOps approaches. This is achieved with the help of tools like <a href="https://docs.ansible.com/" target="_blank" rel="noreferrer">Ansible</a>, <a href="https://cloudinit.readthedocs.io/en/latest/" target="_blank" rel="noreferrer">cloud-init</a>, and <a href="https://argo-cd.readthedocs.io/en/stable/" target="_blank" rel="noreferrer">Argo CD</a>.</p><p>The project incorporates several critical services within the Kubernetes ecosystem, including:</p><ul><li><strong>Distributed Block Storage:</strong> for POD&#39;s persistent volumes via <a href="https://longhorn.io/" target="_blank" rel="noreferrer">LongHorn</a>.</li><li><strong>Backup and Restore Solution:</strong> for the cluster using <a href="https://velero.io/" target="_blank" rel="noreferrer">Velero</a> and <a href="https://restic.net/" target="_blank" rel="noreferrer">Restic</a>.</li><li><strong>Service Mesh Architecture:</strong> facilitated by <a href="https://linkerd.io/" target="_blank" rel="noreferrer">Linkerd</a>.</li><li><strong>Observability Platform:</strong> encompassing a metrics monitoring solution with <a href="https://prometheus.io/" target="_blank" rel="noreferrer">Prometheus</a>, a logging and analytics solution via the EFK+LG stack (<a href="https://www.elastic.co/elasticsearch/" target="_blank" rel="noreferrer">Elasticsearch</a>-<a href="https://www.fluentd.org/" target="_blank" rel="noreferrer">Fluentd</a>/<a href="https://fluentbit.io/" target="_blank" rel="noreferrer">Fluentbit</a>-<a href="https://www.elastic.co/kibana/" target="_blank" rel="noreferrer">Kibana</a> + <a href="https://grafana.com/oss/loki/" target="_blank" rel="noreferrer">Loki</a>-<a href="https://grafana.com/oss/grafana/" target="_blank" rel="noreferrer">Grafana</a>), and a distributed tracing solution through <a href="https://grafana.com/oss/tempo/" target="_blank" rel="noreferrer">Tempo</a>.</li></ul><p>In addition to these services, the project project scope encompasses tools and services pivotal for exploring and understanding microservices architectures:</p><ul><li><p><strong>Service Mesh Architecture with <a href="https://linkerd.io/" target="_blank" rel="noreferrer"><strong><code>Linkerd</code></strong></a>:</strong> This tool enhances service interactions, making them more secure, observable, and reliable without altering application code.</p></li><li><p><strong>API Security:</strong> Utilizing OAuth 2.0 and OpenID Connect, alongside an IAM solution like <a href="https://www.keycloak.org/" target="_blank" rel="noreferrer"><strong><code>Keycloak</code></strong></a>, ensures secure and authorized access across our services.</p></li><li><p><strong>Streaming with Kafka:</strong> <a href="https://kafka.apache.org/" target="_blank" rel="noreferrer"><strong><code>Kafka</code></strong></a> supports real-time data streaming and inter-service communication, crucial for dynamic microservices environments.</p></li></ul><h2 id="design-principles" tabindex="-1">Design Principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to &quot;Design Principles&quot;">​</a></h2><ul><li><strong>ARM Bare Metal Nodes:</strong> Integration of Raspberry PI and Orange Pis nodes (ARM) within the same cluster.</li><li><strong>Lightweight Kubernetes Distribution:</strong> Adoption of <a href="https://k3s.io/" target="_blank" rel="noreferrer">K3S</a>, suitable for Raspberry PI nodes due to its reduced memory requirements.</li><li><strong>Distributed Block Storage Technology:</strong> Preference for Kubernetes distributed storage solutions like <a href="https://rook.io/" target="_blank" rel="noreferrer">Rook/Ceph</a> or <a href="https://longhorn.io/" target="_blank" rel="noreferrer">Longhorn</a>, with recent ARM 64-bit support.</li><li><strong>Commitment to Open Source:</strong> Utilization of projects under the <a href="https://www.cncf.io/" target="_blank" rel="noreferrer">CNCF: Cloud Native Computing Foundation</a>.</li><li><strong>Latest Versions for Exploration:</strong> Utilizing the latest versions of each open-source project to explore cutting-edge Kubernetes capabilities.</li><li><strong>Deployment Automation:</strong> Using <a href="https://cloudinit.readthedocs.io/en/latest/" target="_blank" rel="noreferrer">cloud-init</a> for initial OS setup.</li><li><strong>Configuration Automation:</strong> Using <a href="https://docs.ansible.com/" target="_blank" rel="noreferrer">Ansible</a> for automating the configuration of cluster nodes, Kubernetes and external service installation, and initiation of cluster bootstrap.</li><li><strong>Application Provisioning with Argo CD:</strong> Applying <a href="https://argo-cd.readthedocs.io/en/stable/" target="_blank" rel="noreferrer">Argo CD</a> for seamless Kubernetes application provisioning from a Git repository.</li></ul><h2 id="open-source-technologies-building-the-cluster" tabindex="-1">Open Source Technologies: Building the Cluster <a class="header-anchor" href="#open-source-technologies-building-the-cluster" aria-label="Permalink to &quot;Open Source Technologies: Building the Cluster&quot;">​</a></h2><p>The image below presents a comprehensive view of the open-source technologies utilized in constructing the cluster:</p><p align="center"><img alt="pikube-technical-stacks" src="'+N+'" width="100%" height="100%"></p><div class="d-flex"><table class="table table-white table-bordered border-dark w-auto align-middle"><thead><tr><th></th><th></th><th>Technology Stack</th><th>Description</th></tr></thead><tbody><tr><td rowspan="8" class="vertical-cell"><div class="vertical-text">OBSERVABILITY</div></td><td><img width="32" src="'+s+'" alt="Grafana Logo"></td><td><a href="https://grafana.com/oss/grafana/">Grafana</a></td><td>Monitoring Dashboards.</td></tr><tr><td><img width="32" src="'+n+'" alt="Kibana Logo"></td><td><a href="https://www.elastic.co/kibana/">Kibana</a></td><td>Logs Analytics Dashboards.</td></tr><tr><td><img width="32" src="'+l+'" alt="Elasticsearch Logo"></td><td><a href="https://www.elastic.co/elasticsearch/">Elasticsearch</a></td><td>Logs Analytics.</td></tr><tr><td><img width="32" src="'+d+'" alt="Tempo Logo"></td><td><a href="https://grafana.com/oss/tempo/">Tempo</a></td><td>Distributed Tracing Monitoring.</td></tr><tr><td><img width="32" src="'+c+'" alt="Prometheus Logo"></td><td><a href="https://prometheus.io/">Prometheus</a></td><td>Metrics Monitoring and Alerting.</td></tr><tr><td><img width="32" src="'+h+'" alt="Fluentd Logo"></td><td><a href="https://www.fluentd.org/">Fluentd</a></td><td>Logs Forwarding and Distribution.</td></tr><tr><td><img width="60" src="'+g+'" alt="Fluentbit Logo"></td><td><a href="https://fluentbit.io/">Fluentbit</a></td><td>Logs Collection.</td></tr><tr><td><img width="32" src="'+p+'" alt="Loki Logo"></td><td><a href="https://grafana.com/oss/loki/">Loki</a></td><td>Logs Aggregation.</td></tr><tr><td rowspan="3" class="vertical-cell"><div class="vertical-text">AUTOMATION</div></td><td><img width="32" src="'+u+'" alt="Ansible Logo"></td><td><a href="https://www.ansible.com">Ansible</a></td><td>Streamlines system configuration, external service integration, and k3s cluster setup.</td></tr><tr><td><img width="32" src="'+f+'" alt="ArgoCD Logo"></td><td><a href="https://argoproj.github.io/cd">ArgoCD</a></td><td>Deploys Kubernetes applications following GitOps principles.</td></tr><tr><td><img width="32" src="'+m+'" alt="Cloud-init Logo"></td><td><a href="https://cloudinit.readthedocs.io/en/latest/">Cloud-init</a></td><td>Automates the initial configuration and setup of operating systems.</td></tr><tr><td rowspan="2" class="vertical-cell"><div class="vertical-text">AUTHENTICATION</div></td><td><img width="32" src="'+b+'" alt="Keycloak Logo"></td><td><a href="https://www.keycloak.org/">Keycloak</a></td><td>Open-source Identity and Access Management solution for modern applications and services.</td></tr><tr><td><img width="32" src="'+v+'" alt="OAuth2.0 Proxy Logo"></td><td><a href="https://oauth2-proxy.github.io/oauth2-proxy/">OAuth2.0 Proxy</a></td><td>A reverse proxy and static file server that provides authentication using providers like Keycloak, Google, and others.</td></tr><tr><td rowspan="2" class="vertical-cell"><div class="vertical-text">ORCHESTRATION</div></td><td><img width="32" src="'+w+'" alt="K3S Logo"></td><td><a href="https://k3s.io/">K3S</a></td><td>A simplified and lightweight Kubernetes distribution.</td></tr><tr><td><img width="32" src="'+k+'" alt="containerd Logo"></td><td><a href="https://containerd.io/">containerd</a></td><td>K3S-integrated runtime for container management.</td></tr><tr><td rowspan="3" class="vertical-cell"><div class="vertical-text">SECURITY</div></td><td><img width="32" src="'+_+'" alt="Cert-manager Logo"></td><td><a href="https://cert-manager.io">Cert-manager</a></td><td>Manages TLS certificates for Kubernetes.</td></tr><tr><td><img width="32" src="'+e+'" alt="Vault Logo"></td><td><a href="https://www.vaultproject.io/">Hashicorp Vault</a></td><td>Secures, stores, and tightly controls access to tokens, passwords, certificates, and other sensitive secrets in modern computing.</td></tr><tr><td><img width="32" src="'+y+'" alt="External Secrets Logo"></td><td><a href="https://external-secrets.io/">External Secrets Operator</a></td><td>Synchronizes secrets from external APIs like Hashicorp Vault into Kubernetes.</td></tr><tr><td rowspan="2" class="vertical-cell"><div class="vertical-text">STORAGE</div></td><td><img width="32" src="'+S+'" alt="Longhorn Logo"></td><td><a href="https://longhorn.io/">Longhorn</a></td><td>Distributed storage solution for Kubernetes, ensuring data persistence.</td></tr><tr><td><img width="60" src="'+r+'" alt="Minio Logo"></td><td><a href="https://min.io/">Minio</a></td><td>Efficient S3-compatible object storage system.</td></tr><tr><td rowspan="7" class="vertical-cell"><div class="vertical-text">NETWORK</div></td><td><img width="32" src="'+L+'" alt="CoreDNS Logo"></td><td><a href="https://coredns.io/">CoreDNS</a></td><td>Provides DNS services within the Kubernetes environment.</td></tr><tr><td><img width="32" src="'+A+'" alt="Flannel Logo"></td><td><a href="https://github.com/flannel-io/flannel">Flannel</a></td><td>Network interface for Kubernetes, integrated with K3S.</td></tr><tr><td><img width="32" src="'+P+'" alt="HA Proxy Logo"></td><td><a href="https://www.haproxy.org/">HA Proxy</a></td><td>Load balancer for high availability in Kubernetes API.</td></tr><tr><td><img width="32" src="'+x+'" alt="Metal LB Logo"></td><td><a href="https://metallb.universe.tf/">Metal LB</a></td><td>Bare metal load-balancing solution for Kubernetes.</td></tr><tr><td><img width="32" src="'+C+'" alt="Ingress NGINX Logo"></td><td><a href="https://kubernetes.github.io/ingress-nginx/">Ingress NGINX</a></td><td>Manages external access to the services in a Kubernetes cluster.</td></tr><tr><td><img width="32" src="'+K+'" alt="Traefik Logo"></td><td><a href="https://traefik.io/">Traefik</a></td><td>Alternative Ingress Controller for Kubernetes, providing HTTP routing and load balancing.</td></tr><tr><td><img width="32" src="'+T+'" alt="Linkerd Logo"></td><td><a href="https://linkerd.io/">Linkerd</a></td><td>Provides a service mesh for Kubernetes, enhancing network communication.</td></tr><tr><td rowspan="2" class="vertical-cell"><div class="vertical-text">BACKUP</div></td><td><img width="32" src="'+I+'" alt="Velero Logo"></td><td><a href="https://velero.io/">Velero</a></td><td>Offers backup and restore functionalities for Kubernetes clusters, ensuring data protection.</td></tr><tr><td><img width="32" src="'+D+'" alt="Restic Logo"></td><td><a href="https://restic.net/">Restic</a></td><td>Secure and efficient backup solution, capable of managing file-level backups.</td></tr></tbody></table></div><h2 id="required-external-services-and-resources" tabindex="-1">Required External Services and Resources <a class="header-anchor" href="#required-external-services-and-resources" aria-label="Permalink to &quot;Required External Services and Resources&quot;">​</a></h2><p>This section outlines necessary external services and resources for the homelab setup. While the primary goal is to host services within the Kubernetes cluster, certain external resources are essential.</p><h3 id="cloud-based-external-services" tabindex="-1">Cloud-Based External Services <a class="header-anchor" href="#cloud-based-external-services" aria-label="Permalink to &quot;Cloud-Based External Services&quot;">​</a></h3><blockquote><p>📌 <strong>Note</strong></p><p><em>The use of these external resources is optional. The homelab can function without them, but it will lack verified TLS certificates.</em></p></blockquote><div class="d-flex"><table class="table table-white table-bordered border-dark w-auto align-middle"><thead><tr><th></th><th></th><th>Service Provider</th><th>Essential Resources</th><th>Strategic Importance</th></tr></thead><tbody><tr><td rowspan="2" class="vertical-cell"><div class="vertical-text">SECURITY</div></td><td><img width="200" src="'+E+'" alt="Let&#39;s Encrypt Logo"></td><td><a href="https://letsencrypt.org/">Let&#39;s Encrypt</a></td><td>TLS Certificate Authority</td><td>Issuing verified TLS certificates for secure web communications.</td></tr><tr><td><img width="150" src="'+O+'" alt="Cloudflare Logo"></td><td><a href="https://www.cloudflare.com/">Cloudflare</a></td><td>Web Security &amp; CDN</td><td>Provides DDoS mitigation and performance enhancement via CDN.</td></tr></tbody></table></div><h3 id="alternative-approaches-for-certificate-management-and-dns-configuration" tabindex="-1">Alternative Approaches for Certificate Management and DNS Configuration <a class="header-anchor" href="#alternative-approaches-for-certificate-management-and-dns-configuration" aria-label="Permalink to &quot;Alternative Approaches for Certificate Management and DNS Configuration&quot;">​</a></h3><p><strong>Option 1: Implementing a Private PKI:</strong></p><ul><li><strong><code>Description</code></strong>: A private Public Key Infrastructure (PKI) can be set up to sign TLS certificates internally.</li><li><strong>Implementation Status</strong>: This option is currently feasible with only minimal adjustments necessary.</li><li><strong><code>Reference</code></strong>: For detailed implementation steps, refer to the &quot;Quick Start&quot; guide in the documentation.</li></ul><p><strong>Option 2: Utilizing Alternative DNS Providers:</strong></p><ul><li><strong><code>Context</code></strong>: Cert-manager or Certbot, which are tools for automatic certificate acquisition from Let&#39;s Encrypt, can be adapted for use with various DNS providers.</li><li><strong><code>Adaptation Requirements</code></strong>: Modifying the deployment approach of the cert-manager application is necessary. This involves integrating new DNS providers and possibly adding additional webhooks or plugins.</li><li><strong><code>Current Configuration</code></strong>: Presently, the system is configured with the ACME issuer (specifically Let&#39;s Encrypt) using Cloudflare as the DNS-01 challenge provider.</li><li><strong><code>Further Information</code></strong>: For a comprehensive list of DNS01 challenge providers compatible with this setup, please consult the <a href="https://cert-manager.io/docs/configuration/acme/dns01/#supported-dns01-providers" target="_blank" rel="noreferrer"><strong><code>cert-manager documentation</code></strong></a> regarding supported DNS01 providers.</li></ul><h2 id="externally-hosted-services" tabindex="-1">Externally Hosted Services <a class="header-anchor" href="#externally-hosted-services" aria-label="Permalink to &quot;Externally Hosted Services&quot;">​</a></h2><p>This section outlines specific services hosted outside the Kubernetes cluster. The decision to self-host these services has been made for various strategic reasons.</p><h3 id="service-overview" tabindex="-1">Service Overview <a class="header-anchor" href="#service-overview" aria-label="Permalink to &quot;Service Overview&quot;">​</a></h3><div class="d-flex"><table class="table table-white table-bordered border-dark w-auto align-middle"><thead><tr><th scope="col"></th><th scope="col"></th><th scope="col">Technology Stack</th><th scope="col">Strategic Importance</th></tr></thead><tbody><tr><td rowspan="2" class="vertical-cell"><div class="vertical-text">STRATEGIC SERVICES</div></td><td><img width="60" src="'+r+'" alt="Minio Logo"></td><td><a href="https://min.io/">Minio</a></td><td>S3 Object Store.</td></tr><tr><td><img width="32" src="'+e+'" alt="Vault Logo"></td><td><a href="https://www.vaultproject.io/">Hashicorp Vault</a></td><td>Secrets Management.</td></tr></tbody></table></div><p><strong>Minio:</strong></p><ul><li><strong><code>Hosting Environment</code></strong>: Initially deployed on a BlueBerry Node, with plans for future migration to a Virtual Machine.</li><li><strong><code>Location</code></strong>: Presently operating within local infrastructure, with a roadmap to transition to Azure or Oracle Cloud Infrastructure&#39;s Free Tier.</li><li><strong><code>Function</code></strong>: Provides an S3-compatible object storage solution for backing up cluster data.</li></ul><p><strong>Hashicorp Vault</strong>:</p><ul><li><strong><code>Hosting Environment</code></strong>: Gateway Node</li><li><strong><code>Location</code></strong>: Local Infrastructure</li><li><strong><code>Function</code></strong>: Manages and secures access to sensitive data and secrets. It is locally hosted due to its requirement for direct access to the Kubernetes API, making it unsuitable for public cloud hosting. These services are integral to the cluster&#39;s functionality, offering essential data backup and secure secrets management solutions.</li></ul>',31))])}const Z=R(V,[["render",H]]);export{Q as __pageData,Z as default};
